import React from 'react';
import { Box, Grid, Skeleton, Stack } from '@mui/material';

export interface FinancePageSkeletonProps {
  variant?: 'hub' | 'list' | 'form' | 'simple';
}

export const FinancePageSkeleton: React.FC<FinancePageSkeletonProps> = ({ variant = 'simple' }) => {
  if (variant === 'hub') {
    return (
      <Box data-testid="finance-page-skeleton">
        <Skeleton variant="text" width="72%" height={28} sx={{ mb: 2 }} />
        <Skeleton variant="rounded" height={220} sx={{ mb: 3 }} />
        <Skeleton variant="text" width={240} height={32} sx={{ mb: 1.5 }} />
        <Grid container spacing={2}>
          {[0, 1, 2, 3].map((key) => (
            <Grid item xs={12} md={6} key={key}>
              <Skeleton variant="rounded" height={180} />
            </Grid>
          ))}
        </Grid>
      </Box>
    );
  }

  if (variant === 'list') {
    return (
      <Box data-testid="finance-page-skeleton">
        <Skeleton variant="text" width="60%" height={24} sx={{ mb: 2 }} />
        <Skeleton variant="rounded" height={72} sx={{ mb: 2 }} />
        <Stack spacing={1.5}>
          {[0, 1, 2, 3, 4].map((key) => (
            <Skeleton key={key} variant="rounded" height={56} />
          ))}
        </Stack>
      </Box>
    );
  }

  if (variant === 'form') {
    return (
      <Box>
        <Skeleton variant="text" width={280} height={36} sx={{ mb: 2 }} />
        <Skeleton variant="rounded" height={48} sx={{ mb: 3 }} />
        <Stack spacing={2}>
          {[0, 1, 2, 3].map((key) => (
            <Skeleton key={key} variant="rounded" height={56} />
          ))}
        </Stack>
      </Box>
    );
  }

  return (
    <Box data-testid="finance-page-skeleton" sx={{ py: 2 }}>
      <Stack spacing={2}>
        <Skeleton variant="rounded" height={120} />
        <Skeleton variant="rounded" height={160} />
        <Skeleton variant="rounded" height={160} />
      </Stack>
    </Box>
  );
};

export default FinancePageSkeleton;
